/* ============================================================
   SAA — System Analyst Assessment · question bank

   Original knowledge-check items for systems / integration /
   technical business analysts. Domains:
     • APIs & REST         (design, good vs bad, HTTP semantics)
     • Protocols           (REST vs SOAP, gRPC, GraphQL, WebSockets)
     • Networking & OSI     (the 7 layers, TCP/UDP, DNS, TLS)
     • Messaging & Queues   (RabbitMQ/AMQP, delivery guarantees, Kafka)
     • Databases & Data     (SQL/NoSQL, normalization, ACID, indexing)

   The engine INTERLEAVES questions at runtime so no two adjacent
   items share a topic — authoring stays in readable blocks.

   Schema (consumed by app.js):
     cat     : one of the keys in `categories`
     topic   : sub-type (used for interleaving + weak-area analysis)
     diff    : 1 moderate · 2 hard · 3 very hard
     prompt  : question text (may contain inline HTML)
     options : 3–5 answer strings
     answer  : index of the correct option
     explain : one-line worked answer shown in review
   ============================================================ */
window.MMAT = {
  config: {
    durationSec: 900,       // full forms: 15 minutes
    freeDurationSec: 900,   // the free test is the real thing, full length
    diffLabels: { 1: "Moderate", 2: "Hard", 3: "Very hard" },
  },

  categories: {
    apis:      { label: "APIs & REST",        color: "#5aa9e6" },
    protocols: { label: "Protocols",          color: "#46c98b" },
    network:   { label: "Networking & OSI",   color: "#d9b25a" },
    messaging: { label: "Messaging & Queues", color: "#c98bd9" },
    data:      { label: "Databases & Data",   color: "#e6795a" },
  },

  /* -------- FREE full test (25 questions, 5 per domain) -------- */
  freeTest: {
    id: "free", name: "Free full test", free: true, durationSec: 900,
    blurb: "The real thing, free: 25 questions across all five domains in a full 15 minutes.",
    questions: [
      /* extra set */
      { cat: "apis", topic: "HTTP methods", diff: 1, prompt: "Which HTTP method retrieves only a resource's headers — handy for checking existence or size without downloading the body?", options: ["GET", "HEAD", "TRACE", "CONNECT"], answer: 1, explain: "HEAD returns the same headers as GET but no body — useful for existence, size and last-modified checks." },
      { cat: "protocols", topic: "WebSockets", diff: 2, prompt: "How do Server-Sent Events (SSE) differ from WebSockets?", options: ["SSE and WebSockets are the same protocol", "SSE are full-duplex", "SSE are one-way (server → client); WebSockets are full-duplex", "SSE are binary-only"], answer: 2, explain: "SSE stream one way from server to client over HTTP; WebSockets are a persistent full-duplex channel." },
      { cat: "network", topic: "IP & ports", diff: 2, prompt: "What does Network Address Translation (NAT) let you do?", options: ["Let many private hosts share one public IP address", "Encrypt traffic end to end", "Resolve hostnames to IP addresses", "Balance load by URL path"], answer: 0, explain: "NAT rewrites addresses so a whole private network reaches the internet through one (or a few) public IPs." },
      { cat: "messaging", topic: "Async patterns", diff: 2, prompt: "<span class='mono'>OrderPlaced</span> (a fact that happened) versus <span class='mono'>PlaceOrder</span> (a request to do something) is the distinction between:", options: ["A queue and an exchange", "TCP and UDP", "A row and a table", "An event and a command"], answer: 3, explain: "Events describe something that already happened; commands request an action — it shapes how services couple." },
      { cat: "data", topic: "Keys & constraints", diff: 2, prompt: "How does a <span class='mono'>UNIQUE</span> constraint differ from a <span class='mono'>PRIMARY KEY</span>?", options: ["They are identical", "UNIQUE may allow NULLs and a table can have several; a PRIMARY KEY is single and NOT NULL", "UNIQUE cannot be indexed", "PRIMARY KEY allows duplicate values"], answer: 1, explain: "A table has exactly one primary key (unique + not null); you can define many unique constraints, which typically permit NULLs." },
      /* APIs */
      { cat: "apis", topic: "REST principles", diff: 1, prompt: "Which endpoint best follows REST resource-naming conventions for fetching the orders of user 123?", options: ["<span class='mono'>GET /users/123/orders</span>", "<span class='mono'>GET /getUserOrders?id=123</span>", "<span class='mono'>POST /users/123/orders/list</span>", "<span class='mono'>GET /orders/fetchByUser/123</span>"], answer: 0, explain: "REST models nouns/resources and uses the HTTP verb for the action: GET on the /users/{id}/orders collection." },
      { cat: "apis", topic: "API design", diff: 2, prompt: "Which of these is the clearest sign of a <b>badly</b> designed REST API?", options: ["Verbs in the path, e.g. <span class='mono'>/createOrder</span> and <span class='mono'>/deleteOrder</span>", "Plural nouns for collections, e.g. <span class='mono'>/orders</span>", "Using <span class='mono'>404</span> for a missing resource", "Returning <span class='mono'>201 Created</span> with a <span class='mono'>Location</span> header"], answer: 0, explain: "Actions belong in the HTTP method, not the URL — /createOrder duplicates what POST already expresses." },
      { cat: "apis", topic: "Status codes", diff: 1, prompt: "An API returns <span class='mono'>HTTP 200 OK</span> with body <span class='mono'>{\"error\":\"not found\"}</span> for a missing record. What is the main problem?", options: ["Clients and caches see success — errors must use a 4xx/5xx status", "The body should be XML", "200 is only for POST", "Nothing — the body explains the error"], answer: 0, explain: "The status line is the contract; returning 200 for a failure misleads clients, proxies and caches. Use 404." },
      { cat: "apis", topic: "Idempotency", diff: 2, prompt: "Which statement about HTTP method <b>idempotency</b> is correct?", options: ["<span class='mono'>DELETE</span> is idempotent: repeating it leaves the same end state", "<span class='mono'>POST</span> is idempotent by definition", "<span class='mono'>GET</span> may safely change server state", "<span class='mono'>PUT</span> must create a new resource on every call"], answer: 0, explain: "GET/PUT/DELETE are idempotent (same effect if repeated); POST is not, which is why retries can duplicate." },

      /* Protocols */
      { cat: "protocols", topic: "REST vs SOAP", diff: 1, prompt: "Which is a defining difference between SOAP and REST?", options: ["SOAP is a strict XML-based protocol with an envelope; REST is an architectural style over HTTP", "REST always uses XML; SOAP always uses JSON", "SOAP cannot run over HTTP", "REST requires a WSDL contract"], answer: 0, explain: "SOAP is a protocol (rigid XML envelope, WS-* standards); REST is a style that typically uses JSON over plain HTTP." },
      { cat: "protocols", topic: "SOAP & WSDL", diff: 2, prompt: "In the SOAP world, what does a <span class='mono'>WSDL</span> document describe?", options: ["The service contract: operations, message types and endpoints", "The database schema behind the service", "The TLS certificate chain", "The load-balancer configuration"], answer: 0, explain: "WSDL (Web Services Description Language) is the machine-readable contract for a SOAP service's operations and messages." },
      { cat: "protocols", topic: "gRPC", diff: 2, prompt: "Which pair of technologies is most associated with gRPC?", options: ["HTTP/2 transport and Protocol Buffers", "HTTP/1.1 and XML", "WebSockets and JSON-RPC", "SMTP and MIME"], answer: 0, explain: "gRPC runs over HTTP/2 and serialises with Protocol Buffers, enabling streaming and compact binary messages." },
      { cat: "protocols", topic: "GraphQL", diff: 2, prompt: "What problem does GraphQL most directly address compared with a typical REST API?", options: ["Over- and under-fetching — the client asks for exactly the fields it needs", "Encrypting traffic in transit", "Guaranteeing message delivery", "Enforcing database normalization"], answer: 0, explain: "GraphQL lets the client specify the shape of the response in one request, avoiding many round-trips and unused fields." },

      /* Networking & OSI */
      { cat: "network", topic: "OSI layers", diff: 1, prompt: "At which OSI layer does the <b>HTTP</b> protocol operate?", options: ["Layer 7 — Application", "Layer 4 — Transport", "Layer 3 — Network", "Layer 2 — Data Link"], answer: 0, explain: "HTTP is an application-layer (Layer 7) protocol; it relies on TCP at Layer 4 beneath it." },
      { cat: "network", topic: "OSI layers", diff: 2, prompt: "A device that forwards packets between networks using IP addresses operates primarily at which OSI layer?", options: ["Layer 3 — Network (a router)", "Layer 2 — Data Link (a switch)", "Layer 4 — Transport", "Layer 7 — Application"], answer: 0, explain: "Routing by IP address is a Network-layer (Layer 3) job — that's what a router does; a switch works at Layer 2 by MAC." },
      { cat: "network", topic: "TCP vs UDP", diff: 1, prompt: "Which protocol gives reliable, connection-oriented, ordered delivery?", options: ["TCP", "UDP", "ICMP", "ARP"], answer: 0, explain: "TCP establishes a connection and guarantees ordered, reliable delivery; UDP is connectionless and best-effort." },
      { cat: "network", topic: "TLS/security layer", diff: 2, prompt: "In the classic OSI model, encryption/decryption of data is traditionally associated with which layer?", options: ["Layer 6 — Presentation", "Layer 1 — Physical", "Layer 3 — Network", "Layer 4 — Transport"], answer: 0, explain: "The Presentation layer (6) handles translation, encryption and compression of the data format — hence 'presentation'." },

      /* Messaging & Queues */
      { cat: "messaging", topic: "Exchanges & routing", diff: 2, prompt: "In RabbitMQ, which exchange type delivers a copy of each message to <b>every</b> bound queue, ignoring the routing key?", options: ["Fanout", "Direct", "Topic", "Headers"], answer: 0, explain: "A fanout exchange broadcasts to all bound queues — ideal for pub/sub. Direct/topic route by key/pattern." },
      { cat: "messaging", topic: "Ack & prefetch", diff: 2, prompt: "What does a RabbitMQ consumer send to confirm a message was processed so the broker can drop it?", options: ["An acknowledgement (<span class='mono'>basic.ack</span>)", "A heartbeat frame", "A new binding", "A <span class='mono'>200 OK</span>"], answer: 0, explain: "With manual acks, the broker keeps a delivered message until the consumer acks it; without an ack it can be re-queued." },
      { cat: "messaging", topic: "Delivery guarantees", diff: 2, prompt: "A system guarantees a message is delivered <b>at least once</b>. What must consumers therefore be?", options: ["Idempotent — safe to process the same message twice", "Single-threaded", "Stateless about ordering", "Written in the same language as the producer"], answer: 0, explain: "At-least-once means duplicates are possible on retry, so processing must be idempotent to stay correct." },
      { cat: "messaging", topic: "Kafka vs RabbitMQ", diff: 2, prompt: "Which is the better description of Apache Kafka versus RabbitMQ?", options: ["Kafka is a partitioned, replayable log; RabbitMQ is a broker that routes and removes messages once acked", "They are identical", "Kafka cannot scale horizontally", "RabbitMQ stores an immutable log consumers replay by offset"], answer: 0, explain: "Kafka retains an ordered log consumers read by offset (replayable); RabbitMQ pushes/routes messages that leave the queue once acknowledged." },

      /* Databases & Data */
      { cat: "data", topic: "ACID", diff: 1, prompt: "In ACID, what does the <b>D</b> stand for, and what does it promise?", options: ["Durability — once committed, data survives crashes", "Distribution — data is sharded", "Delegation — writes are queued", "Determinism — queries always return the same rows"], answer: 0, explain: "Durability means a committed transaction is persisted (e.g. to disk/WAL) and will survive a subsequent failure." },
      { cat: "data", topic: "Normalization", diff: 2, prompt: "You store the customer's name and address on every order row. Which problem does this most directly cause?", options: ["Update anomalies and redundancy — a normalized design would reference a customer table", "Loss of durability", "Broken TLS", "Automatic deadlocks"], answer: 0, explain: "Repeating customer data across orders is denormalized; changing an address means many rows to update — an update anomaly." },
      { cat: "data", topic: "Indexing", diff: 2, prompt: "Which index structure is the default in most relational databases and supports range scans efficiently?", options: ["B-tree", "Hash", "Bitmap", "Inverted (full-text)"], answer: 0, explain: "B-tree indexes keep keys sorted, so they serve both equality and range queries (<, >, BETWEEN) well." },
      { cat: "data", topic: "Isolation levels", diff: 3, prompt: "Under the <span class='mono'>READ COMMITTED</span> isolation level, which anomaly is still possible?", options: ["Non-repeatable reads", "Dirty reads", "Reading uncommitted data", "None — it is the strictest level"], answer: 0, explain: "READ COMMITTED blocks dirty reads but a row can change between two reads in the same transaction — a non-repeatable read." },
    ],
  },

  /* -------- TEN FULL FORMS (20 questions each) -------- */
  tests: [
    /* ===================== TEST 1 ===================== */
    { id: "form-1", name: "Test 1", locked: true, blurb: "Core REST semantics, the OSI stack and everyday database design.",
      questions: [
        /* extra set */
        { cat: "apis", topic: "Status codes", diff: 1, prompt: "A DELETE succeeds and there is nothing to return. The cleanest status is:", options: ["404 Not Found", "200 OK with an empty body", "204 No Content", "202 Accepted"], answer: 2, explain: "204 says 'done, no body to send' — the tidy choice for a successful delete with no representation." },
        { cat: "protocols", topic: "HTTP protocol", diff: 2, prompt: "HTTP/3 runs over which transport?", options: ["QUIC, which runs over UDP", "Plain TCP", "SMTP", "A WebSocket"], answer: 0, explain: "HTTP/3 uses QUIC (over UDP), avoiding TCP head-of-line blocking while keeping reliability and TLS built in." },
        { cat: "network", topic: "IP & ports", diff: 1, prompt: "Ports below 1024 are known as:", options: ["Randomly assigned client ports", "Always blocked by firewalls", "UDP-only ports", "Well-known ports for common services (80, 443, 22…)"], answer: 3, explain: "The 0–1023 range is reserved for well-known services; clients use high, ephemeral source ports." },
        { cat: "messaging", topic: "Queues & DLQ", diff: 2, prompt: "A priority queue in a message broker lets:", options: ["Consumers skip acknowledgements", "Higher-priority messages be delivered ahead of lower-priority ones", "Producers avoid TLS", "Messages share a Kafka offset"], answer: 1, explain: "Priority queues reorder delivery so urgent messages jump ahead — useful, but can starve low-priority work." },
        { cat: "data", topic: "SQL vs NoSQL", diff: 2, prompt: "OLTP systems handle many small transactions; OLAP systems are optimised for:", options: ["Encrypting rows at rest", "Message routing", "Complex analytical queries over large volumes of data", "Resolving hostnames"], answer: 2, explain: "OLAP (analytics/warehousing) favours big aggregate reads; OLTP favours fast, concurrent small reads/writes." },
        { cat: "apis", topic: "REST principles", diff: 1, prompt: "Which property is a core constraint of REST?", options: ["Statelessness — each request carries all context the server needs", "The server stores each client's session in memory", "Every call must use SOAP envelopes", "Responses must be HTML"], answer: 0, explain: "REST is stateless: the server keeps no client session between requests, which aids scaling and caching." },
        { cat: "apis", topic: "HTTP methods", diff: 1, prompt: "Which HTTP method is the conventional choice to <b>fully replace</b> an existing resource?", options: ["PUT", "GET", "POST", "HEAD"], answer: 0, explain: "PUT replaces the resource at a known URI and is idempotent; POST creates/appends and is not." },
        { cat: "apis", topic: "Status codes", diff: 2, prompt: "A client sends a syntactically valid request but fails a business rule (e.g. insufficient funds). Which status best fits?", options: ["422 Unprocessable Entity", "500 Internal Server Error", "200 OK", "301 Moved Permanently"], answer: 0, explain: "The request was understood but semantically can't be processed → 422 (or a well-chosen 4xx); 500 implies a server bug." },
        { cat: "protocols", topic: "REST vs SOAP", diff: 2, prompt: "For a bank-to-bank integration needing strict contracts, WS-Security and formal transactions, which is the traditional fit?", options: ["SOAP", "Plain REST/JSON", "GraphQL", "WebSockets"], answer: 0, explain: "SOAP's rigid contracts and WS-* standards (security, atomic transactions) suit formal enterprise/finance integrations." },
        { cat: "protocols", topic: "HTTP protocol", diff: 1, prompt: "Which HTTP header tells the server the format the client wants back?", options: ["<span class='mono'>Accept</span>", "<span class='mono'>Content-Type</span>", "<span class='mono'>Host</span>", "<span class='mono'>User-Agent</span>"], answer: 0, explain: "Accept expresses the client's desired response media type; Content-Type describes the body being sent." },
        { cat: "protocols", topic: "gRPC", diff: 2, prompt: "Which capability comes 'for free' with gRPC over HTTP/2 that plain REST/HTTP-1.1 lacks natively?", options: ["Bidirectional streaming over a single connection", "Human-readable JSON payloads", "Statelessness", "Caching by URL"], answer: 0, explain: "HTTP/2 multiplexing lets gRPC stream in both directions on one connection; classic REST is request/response per call." },
        { cat: "network", topic: "OSI layers", diff: 1, prompt: "Which OSI layer is responsible for end-to-end delivery using ports and segments?", options: ["Layer 4 — Transport", "Layer 7 — Application", "Layer 2 — Data Link", "Layer 1 — Physical"], answer: 0, explain: "The Transport layer (TCP/UDP) provides host-to-host delivery and uses port numbers to address processes." },
        { cat: "network", topic: "TCP vs UDP", diff: 2, prompt: "Which use case is the best fit for UDP rather than TCP?", options: ["Live voice/video where late packets are useless", "A bank transfer that must not lose data", "Downloading a software package", "Sending an email"], answer: 0, explain: "Real-time media tolerates loss but not delay, so UDP's low-overhead best-effort model wins over TCP's retransmits." },
        { cat: "network", topic: "DNS", diff: 1, prompt: "What does DNS primarily do?", options: ["Resolve a hostname to an IP address", "Encrypt traffic end to end", "Balance load across servers", "Store user passwords"], answer: 0, explain: "DNS is the internet's naming system: it maps human names like example.com to IP addresses." },
        { cat: "messaging", topic: "AMQP & RabbitMQ", diff: 1, prompt: "In RabbitMQ, where does a producer actually publish a message?", options: ["To an exchange, which routes it to queues", "Directly into a consumer's memory", "To a database table", "To the DNS server"], answer: 0, explain: "Producers publish to an exchange; bindings and routing keys then decide which queue(s) receive it." },
        { cat: "messaging", topic: "Queues & DLQ", diff: 2, prompt: "What is a dead-letter queue (DLQ) used for?", options: ["Capturing messages that were rejected, expired or repeatedly failed", "Storing the fastest-processed messages", "Load-balancing consumers", "Encrypting messages at rest"], answer: 0, explain: "A DLQ collects messages that can't be delivered/processed (nacked, TTL-expired, over max retries) for inspection or retry." },
        { cat: "messaging", topic: "Async patterns", diff: 2, prompt: "Why introduce a message queue between two services instead of a direct synchronous call?", options: ["To decouple them and absorb load spikes so a slow/down consumer doesn't block the producer", "To guarantee lower latency than a direct call", "To avoid needing a network", "To enforce database normalization"], answer: 0, explain: "Queues decouple producer and consumer in time, smoothing spikes and improving resilience — at the cost of added latency." },
        { cat: "data", topic: "SQL vs NoSQL", diff: 1, prompt: "Which workload is the classic fit for a relational (SQL) database?", options: ["Structured data with complex relationships and multi-row transactions", "Storing large opaque binary blobs only", "A schema that changes shape on every write", "Purely append-only event logs at massive scale"], answer: 0, explain: "RDBMSs excel at structured, related data with ACID transactions and rich joins." },
        { cat: "data", topic: "Keys & constraints", diff: 1, prompt: "What does a FOREIGN KEY enforce?", options: ["Referential integrity — the value must exist in the referenced table", "That the column is indexed for speed", "That values are unique", "That the column cannot be null"], answer: 0, explain: "A foreign key ties a child row to a valid parent row, preventing orphaned references." },
        { cat: "data", topic: "Joins", diff: 2, prompt: "An <span class='mono'>INNER JOIN</span> between Orders and Customers returns:", options: ["Only rows where a matching customer exists for the order", "All orders, with nulls where no customer matches", "All customers, matched or not", "The Cartesian product of both tables"], answer: 0, explain: "INNER JOIN keeps only matched pairs; a LEFT JOIN would keep unmatched orders with null customer fields." },
      ],
    },

    /* ===================== TEST 2 ===================== */
    { id: "form-2", name: "Test 2", locked: true, blurb: "Good vs. bad API design, SOAP-vs-REST trade-offs and RabbitMQ routing.",
      questions: [
        /* extra set */
        { cat: "apis", topic: "HTTP protocol", diff: 2, prompt: "Before a cross-origin POST with a custom header, the browser first sends an OPTIONS request. This is the:", options: ["TLS handshake", "CORS preflight", "DNS lookup", "WebSocket upgrade"], answer: 1, explain: "Browsers 'preflight' non-simple cross-origin requests with OPTIONS to check the server's CORS policy before sending the real call." },
        { cat: "protocols", topic: "gRPC", diff: 2, prompt: "Attaching a deadline (timeout) to a gRPC call means:", options: ["The server caches the response", "TLS is skipped", "The message is compressed", "The call is cancelled if it exceeds the time budget"], answer: 3, explain: "gRPC deadlines propagate through the call chain; if exceeded, work is cancelled instead of hanging indefinitely." },
        { cat: "network", topic: "IP & ports", diff: 2, prompt: "ARP (Address Resolution Protocol) maps:", options: ["An IP address to a MAC address on the local link", "A hostname to an IP address", "A port to a process", "A URL to a route"], answer: 0, explain: "ARP finds the hardware (MAC) address for an IP on the same network so frames can be delivered at Layer 2." },
        { cat: "messaging", topic: "Kafka vs RabbitMQ", diff: 2, prompt: "In Kafka, 'consumer lag' measures:", options: ["Network latency to the broker", "Disk usage on the broker", "How far behind the latest offset a consumer group is", "The number of partitions"], answer: 2, explain: "Lag = latest produced offset minus the consumer's committed offset — how far behind real time it is running." },
        { cat: "data", topic: "Keys & constraints", diff: 2, prompt: "<span class='mono'>ON DELETE CASCADE</span> on a foreign key means:", options: ["Deletes are blocked while children exist", "Deleting a parent row also deletes its child rows", "Child rows become primary keys", "The whole table is dropped"], answer: 1, explain: "CASCADE propagates the delete to dependent rows; alternatives are RESTRICT/NO ACTION or SET NULL." },
        { cat: "apis", topic: "API design", diff: 2, prompt: "Which endpoint set is the most RESTful design for a blog's comments?", options: ["<span class='mono'>GET/POST /posts/42/comments</span>, <span class='mono'>DELETE /comments/9</span>", "<span class='mono'>/getComments</span>, <span class='mono'>/addComment</span>, <span class='mono'>/removeComment</span>", "<span class='mono'>/comments?action=create</span>", "<span class='mono'>/do/comment/add</span>"], answer: 0, explain: "Resources as nouns, nested under their parent, with the verb carried by the HTTP method — that's idiomatic REST." },
        { cat: "apis", topic: "Errors & contracts", diff: 2, prompt: "What makes an API error response genuinely useful to client developers?", options: ["A correct status code plus a machine-readable code and human message", "A 200 status with a generic 'something went wrong'", "An HTML stack trace", "An empty body"], answer: 0, explain: "Good errors pair the right HTTP status with a stable error code and a clear message so clients can handle them programmatically." },
        { cat: "apis", topic: "HTTP methods", diff: 2, prompt: "Which method should be <b>safe</b> (no observable side-effects on the server)?", options: ["GET", "POST", "PUT", "PATCH"], answer: 0, explain: "GET (and HEAD) are 'safe' — they must not change state; that's why crawlers can call them freely." },
        { cat: "protocols", topic: "REST vs SOAP", diff: 1, prompt: "Which format does SOAP mandate for its messages?", options: ["XML (inside an Envelope)", "JSON", "YAML", "Protocol Buffers"], answer: 0, explain: "SOAP messages are always XML wrapped in a SOAP Envelope with a Header and Body." },
        { cat: "protocols", topic: "WebSockets", diff: 2, prompt: "What does the WebSocket protocol provide that plain HTTP request/response does not?", options: ["A persistent, full-duplex connection for server push", "Automatic database transactions", "Guaranteed message ordering across servers", "Built-in schema validation"], answer: 0, explain: "WebSockets upgrade the connection to full-duplex, letting the server push data without the client polling." },
        { cat: "protocols", topic: "Protocol choice", diff: 2, prompt: "A dashboard needs live price ticks pushed from the server many times per second. Which is the best fit?", options: ["WebSockets (or SSE)", "SOAP over HTTP", "Polling a REST endpoint every 5 minutes", "FTP"], answer: 0, explain: "Continuous server push is exactly what WebSockets/Server-Sent Events are for; polling adds latency and load." },
        { cat: "network", topic: "OSI layers", diff: 2, prompt: "A network switch that forwards frames using MAC addresses operates at which OSI layer?", options: ["Layer 2 — Data Link", "Layer 3 — Network", "Layer 4 — Transport", "Layer 7 — Application"], answer: 0, explain: "MAC-address forwarding is a Data-Link (Layer 2) function; routing by IP is Layer 3." },
        { cat: "network", topic: "IP & ports", diff: 1, prompt: "Which port does HTTPS use by default?", options: ["443", "80", "22", "25"], answer: 0, explain: "HTTPS defaults to TCP 443; plain HTTP is 80, SSH 22, SMTP 25." },
        { cat: "network", topic: "Encapsulation", diff: 2, prompt: "As data moves down the OSI stack from application to physical, what happens at each layer?", options: ["Each layer adds its own header (encapsulation)", "Each layer removes a header", "The payload is encrypted twice", "Nothing changes until Layer 1"], answer: 0, explain: "Sending encapsulates: each layer wraps the payload with its header; the receiver de-encapsulates on the way up." },
        { cat: "messaging", topic: "Exchanges & routing", diff: 2, prompt: "Which RabbitMQ exchange routes by matching the routing key against patterns with <span class='mono'>*</span> and <span class='mono'>#</span> wildcards?", options: ["Topic", "Direct", "Fanout", "Headers"], answer: 0, explain: "A topic exchange matches routing keys like <span class='mono'>order.eu.*</span> against binding patterns; * = one word, # = zero or more." },
        { cat: "messaging", topic: "Ack & prefetch", diff: 3, prompt: "A consumer sets prefetch (QoS) to 1. What is the effect?", options: ["The broker sends at most one unacked message at a time, spreading load fairly", "Messages are delivered once per second", "Only one consumer may connect", "Messages are deleted after one second"], answer: 0, explain: "Prefetch limits unacknowledged messages in flight per consumer; setting 1 prevents a fast-but-busy consumer from hoarding work." },
        { cat: "messaging", topic: "Idempotent consumers", diff: 2, prompt: "To make an at-least-once consumer safe against duplicate deliveries, a common technique is:", options: ["Deduplicate using a stored message/idempotency key", "Turn off acknowledgements", "Use a fanout exchange", "Increase the TTL"], answer: 0, explain: "Recording processed message IDs (or an idempotency key) lets the consumer ignore repeats and stay correct." },
        { cat: "data", topic: "Normalization", diff: 2, prompt: "Third Normal Form (3NF) removes which kind of dependency?", options: ["Transitive dependencies (non-key attributes depending on other non-key attributes)", "All foreign keys", "Any duplicate rows", "Indexes on non-key columns"], answer: 0, explain: "3NF requires non-key attributes depend only on the key — no transitive dependency via another non-key column." },
        { cat: "data", topic: "Transactions", diff: 2, prompt: "What is the purpose of wrapping several writes in a single transaction?", options: ["Atomicity — all succeed or all roll back together", "To make them run faster", "To skip the indexes", "To bypass constraints"], answer: 0, explain: "A transaction makes multiple statements atomic: either every change commits or none does, keeping data consistent." },
        { cat: "data", topic: "SQL vs NoSQL", diff: 2, prompt: "A key-value store like Redis is the best fit for which need?", options: ["Ultra-fast lookups/caching by a known key", "Ad-hoc joins across many tables", "Strong multi-row ACID reporting", "Full-text ranked search as the primary feature"], answer: 0, explain: "Key-value stores shine at O(1) get/set by key (caching, sessions); they don't do relational joins." },
      ],
    },

    /* ===================== TEST 3 ===================== */
    { id: "form-3", name: "Test 3", locked: true, blurb: "HTTP semantics, transport protocols and transaction behaviour.",
      questions: [
        /* extra set */
        { cat: "apis", topic: "API design", diff: 2, prompt: "A client receives <span class='mono'>429 Too Many Requests</span>. The correct client behaviour is:", options: ["Immediately retry in a tight loop", "Switch the request to POST", "Back off and retry after the Retry-After delay", "Ignore it and keep sending"], answer: 2, explain: "429 means slow down; a good client honours Retry-After and uses exponential backoff instead of hammering the API." },
        { cat: "protocols", topic: "GraphQL", diff: 2, prompt: "In GraphQL, an operation that changes server state is a:", options: ["Mutation", "Query", "Subscription", "Fragment"], answer: 0, explain: "Queries read, mutations write, subscriptions stream updates; fragments are reusable field selections." },
        { cat: "network", topic: "DNS", diff: 2, prompt: "A recursive DNS resolver:", options: ["Only stores the root zone", "Encrypts the whole connection", "Balances TCP load", "Queries other name servers on the client's behalf and returns the final answer"], answer: 3, explain: "The recursive resolver does the legwork (root → TLD → authoritative) and returns the resolved record, caching by TTL." },
        { cat: "messaging", topic: "Async patterns", diff: 3, prompt: "When consumers can't keep up, applying 'backpressure' means:", options: ["Dropping the database", "Slowing or bounding producers/queues so the system isn't overwhelmed", "Disabling acknowledgements", "Adding more DNS records"], answer: 1, explain: "Backpressure pushes the limit upstream (bounded queues, pausing producers) instead of letting memory and latency blow up." },
        { cat: "data", topic: "ACID", diff: 3, prompt: "A write-ahead log (WAL) most directly supports which ACID property?", options: ["Durability", "Isolation", "Consistency", "None of them"], answer: 0, explain: "Changes hit the log before the data pages, so a committed transaction can be recovered after a crash — durability (it also aids atomicity)." },
        { cat: "apis", topic: "Status codes", diff: 1, prompt: "Which status code signals the client is not authenticated (no/invalid credentials)?", options: ["401 Unauthorized", "403 Forbidden", "400 Bad Request", "404 Not Found"], answer: 0, explain: "401 means 'authenticate first'; 403 means 'authenticated but not allowed'." },
        { cat: "apis", topic: "Status codes", diff: 2, prompt: "A client is correctly authenticated but lacks permission for the action. The right status is:", options: ["403 Forbidden", "401 Unauthorized", "409 Conflict", "500 Internal Server Error"], answer: 0, explain: "403 is the classic 'I know who you are, but you may not do this'." },
        { cat: "apis", topic: "Idempotency", diff: 3, prompt: "A payment <span class='mono'>POST</span> may be retried after a network timeout. How do good APIs prevent a double charge?", options: ["Accept an idempotency key so repeats return the original result", "Switch the method to GET", "Return 200 no matter what", "Disable retries on the client"], answer: 0, explain: "An idempotency key lets the server recognise a retried create and return the first outcome instead of charging again." },
        { cat: "protocols", topic: "HTTP protocol", diff: 2, prompt: "What is the main advantage of HTTP/2 over HTTP/1.1?", options: ["Multiplexing many requests over one connection, avoiding app-level head-of-line blocking", "It drops TLS support", "It removes headers entirely", "It only supports GET"], answer: 0, explain: "HTTP/2 multiplexes concurrent streams on a single TCP connection, reducing latency versus 1.1's one-request-at-a-time behaviour." },
        { cat: "protocols", topic: "GraphQL", diff: 2, prompt: "Which is a genuine trade-off of GraphQL versus REST?", options: ["HTTP caching is harder because most queries hit one POST endpoint", "It cannot return JSON", "It requires SOAP envelopes", "It forbids authentication"], answer: 0, explain: "Because queries usually POST to /graphql, standard URL-based HTTP caching doesn't apply the way it does for REST GETs." },
        { cat: "protocols", topic: "Protocol choice", diff: 2, prompt: "Two internal microservices need low-latency, strongly-typed, high-volume calls. Which protocol is the strongest candidate?", options: ["gRPC", "SOAP", "GraphQL over HTTP/1.1", "Email/SMTP"], answer: 0, explain: "gRPC's binary Protobuf over HTTP/2 gives compact, fast, contract-first service-to-service calls." },
        { cat: "network", topic: "TCP vs UDP", diff: 2, prompt: "Which describes the TCP three-way handshake order?", options: ["SYN → SYN-ACK → ACK", "ACK → SYN → FIN", "GET → 200 → CLOSE", "PING → PONG → DATA"], answer: 0, explain: "TCP opens a connection with SYN, SYN-ACK, then ACK before any data flows." },
        { cat: "network", topic: "TLS/security layer", diff: 2, prompt: "What does TLS provide for an HTTPS connection?", options: ["Encryption in transit plus server authentication via certificates", "Storage encryption at rest", "Load balancing", "Database indexing"], answer: 0, explain: "TLS encrypts the channel and authenticates the server (and optionally the client) using X.509 certificates." },
        { cat: "network", topic: "OSI layers", diff: 3, prompt: "Which layer ordering (top to bottom) is correct for the OSI model?", options: ["Application, Presentation, Session, Transport, Network, Data Link, Physical", "Application, Session, Transport, Presentation, Network, Physical, Data Link", "Physical, Data Link, Network, Transport, Session, Presentation, Application", "Transport, Application, Network, Session, Physical, Presentation, Data Link"], answer: 0, explain: "Top-down: All People Seem To Need Data Processing — Application→Presentation→Session→Transport→Network→Data Link→Physical." },
        { cat: "messaging", topic: "Delivery guarantees", diff: 3, prompt: "Which delivery guarantee is the hardest to achieve and usually needs dedup or transactional writes?", options: ["Exactly-once", "At-most-once", "At-least-once", "Best-effort"], answer: 0, explain: "Exactly-once end-to-end is famously hard; systems usually approximate it with at-least-once delivery plus idempotent/dedup processing." },
        { cat: "messaging", topic: "AMQP & RabbitMQ", diff: 2, prompt: "What is a 'binding' in RabbitMQ?", options: ["A rule linking an exchange to a queue (often with a routing key)", "A pool of TCP connections", "A stored procedure", "A consumer's thread"], answer: 0, explain: "A binding connects an exchange to a queue; the routing key/pattern on the binding decides what gets delivered." },
        { cat: "messaging", topic: "Kafka vs RabbitMQ", diff: 2, prompt: "Which need points you toward Kafka rather than RabbitMQ?", options: ["Replaying a retained event stream and scaling reads via partitions", "Simple task queue with per-message routing and TTLs", "Classic RPC-style work distribution", "Priority queues for a few jobs"], answer: 0, explain: "Kafka's partitioned, retained log suits high-throughput event streaming and replay; RabbitMQ suits flexible routing/task queues." },
        { cat: "data", topic: "Isolation levels", diff: 3, prompt: "Which isolation level prevents dirty reads, non-repeatable reads AND phantom reads?", options: ["Serializable", "Read Committed", "Read Uncommitted", "Repeatable Read"], answer: 0, explain: "Serializable is the strictest level and prevents all three anomalies (Repeatable Read still allows phantoms in the SQL standard)." },
        { cat: "data", topic: "ACID", diff: 2, prompt: "The 'C' in ACID (Consistency) means:", options: ["A transaction moves the database from one valid state to another, respecting all constraints", "Reads are always fast", "Data is replicated consistently across nodes", "The schema never changes"], answer: 0, explain: "ACID-Consistency is about honouring defined rules/constraints per transaction — distinct from CAP's 'consistency'." },
        { cat: "data", topic: "Indexing", diff: 2, prompt: "Why can adding many indexes hurt an OLTP database?", options: ["Every insert/update must also maintain each index, slowing writes", "Reads become slower", "It violates ACID", "Indexes delete rows"], answer: 0, explain: "Indexes speed reads but add write overhead and storage — each write updates every affected index." },
      ],
    },

    /* ===================== TEST 4 ===================== */
    { id: "form-4", name: "Test 4", locked: true, blurb: "API versioning & pagination, gRPC/GraphQL and database indexing.",
      questions: [
        /* extra set */
        { cat: "apis", topic: "API design", diff: 2, prompt: "An API gateway in front of microservices typically handles:", options: ["Each service's business logic", "The database schema", "Client-side rendering", "Cross-cutting concerns — routing, auth, rate limiting, TLS termination"], answer: 3, explain: "A gateway centralises edge concerns so individual services don't each reimplement auth, throttling and routing." },
        { cat: "protocols", topic: "Protocol choice", diff: 2, prompt: "Long polling emulates server push by:", options: ["Sending UDP datagrams", "Holding a request open until data is ready, then the client reconnects", "Opening a raw TCP socket", "Publishing a WSDL"], answer: 1, explain: "The server delays the response until it has something to send — simpler than WebSockets but heavier than a true push." },
        { cat: "network", topic: "TLS/security layer", diff: 2, prompt: "A browser trusts a site's TLS certificate because:", options: ["It uses port 443", "The response is compressed", "It chains up to a Certificate Authority the browser already trusts", "The server's IP is public"], answer: 2, explain: "Trust flows from a root CA through intermediates to the leaf certificate; a broken or absent chain triggers a warning." },
        { cat: "messaging", topic: "Kafka vs RabbitMQ", diff: 2, prompt: "In Kafka, choosing a good partition key matters because:", options: ["Messages with the same key land in the same partition, preserving their order", "It encrypts the topic", "It sets the retention period", "It selects the TLS cipher"], answer: 0, explain: "Ordering is per-partition, so related events must share a key to stay ordered — but a skewed key creates hot partitions." },
        { cat: "data", topic: "Denormalization", diff: 2, prompt: "How does a plain SQL <span class='mono'>VIEW</span> differ from a <span class='mono'>MATERIALIZED VIEW</span>?", options: ["A plain view stores a physical copy of the rows", "A plain view runs its query live each time and stores no data; a materialized view stores a refreshed copy", "A plain view cannot be queried", "They are identical"], answer: 1, explain: "Views are virtual (always fresh, recomputed on read); materialized views cache the result for speed and must be refreshed." },
        { cat: "apis", topic: "Versioning", diff: 2, prompt: "Which is a widely-used, cache-friendly way to version a public REST API?", options: ["A version prefix in the path, e.g. <span class='mono'>/v1/orders</span>", "Changing field meanings silently", "A random query flag per client", "Never versioning — just break clients"], answer: 0, explain: "URI versioning (/v1/) is simple and cacheable; header/media-type versioning is an alternative. Silent breaking changes are the anti-pattern." },
        { cat: "apis", topic: "Pagination", diff: 2, prompt: "For a large, frequently-changing feed, which pagination style avoids skipped/duplicated rows better than offset paging?", options: ["Cursor (keyset) pagination", "OFFSET/LIMIT with a growing offset", "Returning everything at once", "Random sampling"], answer: 0, explain: "Cursor/keyset paging anchors on the last seen key, so inserts/deletes don't shift a numeric offset and cause skips or repeats." },
        { cat: "apis", topic: "REST principles", diff: 2, prompt: "HATEOAS, the top of Richardson's REST maturity model, means:", options: ["Responses include links guiding the client to next available actions", "The API uses only HTTPS", "All data is returned as HTML", "The server stores client state"], answer: 0, explain: "HATEOAS (Hypermedia as the Engine of Application State) embeds links/affordances so clients discover transitions dynamically." },
        { cat: "protocols", topic: "gRPC", diff: 2, prompt: "In gRPC, the <span class='mono'>.proto</span> file primarily defines:", options: ["The service methods and message schemas (the contract)", "The TLS certificates", "The database indexes", "The load-balancer rules"], answer: 0, explain: "A .proto declares services, RPC methods and typed messages; code is generated from it for client and server." },
        { cat: "protocols", topic: "GraphQL", diff: 2, prompt: "In GraphQL, what is a 'resolver'?", options: ["A function that fetches the data for a particular field/type", "The TLS handshake step", "A database index", "The client-side cache"], answer: 0, explain: "Resolvers are server functions that return the value for each field in a query, often hitting a DB or another service." },
        { cat: "protocols", topic: "REST vs SOAP", diff: 2, prompt: "Which is generally TRUE when comparing REST/JSON to SOAP/XML for a public web API?", options: ["REST/JSON is lighter-weight and easier for browsers/mobile to consume", "SOAP payloads are smaller than JSON", "REST cannot use HTTPS", "SOAP is schemaless"], answer: 0, explain: "JSON over REST is lighter and browser-friendly; SOAP's XML envelopes and WS-* add weight better suited to strict enterprise needs." },
        { cat: "network", topic: "DNS", diff: 2, prompt: "Which DNS record maps a hostname to an IPv4 address?", options: ["A record", "MX record", "CNAME record", "TXT record"], answer: 0, explain: "An A record points a name to an IPv4 address (AAAA for IPv6); CNAME aliases one name to another; MX is for mail." },
        { cat: "network", topic: "IP & ports", diff: 2, prompt: "What is the role of a port number in TCP/IP?", options: ["It identifies which process/service on the host should receive the traffic", "It encrypts the packet", "It is the physical cable slot", "It is the same as the IP address"], answer: 0, explain: "The IP address locates the host; the port number identifies the specific service/socket on that host (e.g. 443 for HTTPS)." },
        { cat: "network", topic: "Load balancing layer", diff: 2, prompt: "A 'Layer 7 load balancer' can route based on:", options: ["Application data such as the URL path or HTTP headers", "Only the source MAC address", "Only the electrical signal", "Nothing — it just duplicates packets"], answer: 0, explain: "An L7 (application-layer) balancer inspects HTTP details (path, host, cookies) to route; an L4 balancer routes by IP/port only." },
        { cat: "messaging", topic: "Dead-letter & TTL", diff: 2, prompt: "You set a message TTL of 30s on a queue with a dead-letter exchange. A message not consumed in 30s will:", options: ["Expire and be routed to the dead-letter exchange", "Be delivered twice", "Be deleted from every queue in the broker", "Block the producer"], answer: 0, explain: "On TTL expiry the message is dead-lettered (if configured), letting you handle stale work separately." },
        { cat: "messaging", topic: "Async patterns", diff: 2, prompt: "The 'competing consumers' pattern means:", options: ["Multiple consumers read from the same queue to share and scale out work", "Consumers race to corrupt each other's data", "One consumer blocks all others", "Producers compete for a single queue slot"], answer: 0, explain: "Several workers pull from one queue; the broker hands each message to one of them, scaling throughput horizontally." },
        { cat: "messaging", topic: "Exchanges & routing", diff: 1, prompt: "A direct exchange delivers a message to queues whose binding key:", options: ["Exactly equals the message's routing key", "Matches a wildcard pattern", "Is ignored entirely", "Contains the word 'direct'"], answer: 0, explain: "Direct exchanges route on an exact routing-key match; topic exchanges do pattern matching; fanout ignores the key." },
        { cat: "data", topic: "Indexing", diff: 3, prompt: "A query filters on <span class='mono'>(country, city)</span>. A composite index on <span class='mono'>(country, city)</span> helps most because:", options: ["It matches the leftmost-prefix order of the filter", "It indexes city before country", "It forces a full table scan", "Composite indexes only help writes"], answer: 0, explain: "Composite indexes serve queries that use a leftmost prefix of the key — (country) or (country, city), but not (city) alone." },
        { cat: "data", topic: "Joins", diff: 2, prompt: "A <span class='mono'>LEFT OUTER JOIN</span> from Customers to Orders returns:", options: ["All customers, with order columns null where a customer has no orders", "Only customers who have orders", "Only orders with no customer", "The intersection of both tables"], answer: 0, explain: "LEFT JOIN keeps every left-side (Customers) row, filling nulls when there's no matching order." },
        { cat: "data", topic: "SQL vs NoSQL", diff: 2, prompt: "Which is a real downside of a schema-less document database when the data is highly relational?", options: ["Enforcing integrity and doing joins moves into application code", "It cannot store JSON", "It cannot scale horizontally", "It always loses data"], answer: 0, explain: "Document stores trade rigid schemas/joins for flexibility; relational integrity and cross-document joins become the app's job." },
      ],
    },

    /* ===================== TEST 5 ===================== */
    { id: "form-5", name: "Test 5", locked: true, blurb: "Idempotency & caching, real-time protocols and isolation levels.",
      questions: [
        /* extra set */
        { cat: "apis", topic: "API design", diff: 2, prompt: "To notify a partner system of events without them polling you, you expose:", options: ["A bigger GET endpoint", "A SOAP fault", "Webhooks — you POST to a callback URL they register", "A database view"], answer: 2, explain: "Webhooks invert the direction: your server calls theirs when something happens, avoiding constant polling." },
        { cat: "protocols", topic: "gRPC", diff: 3, prompt: "Safely evolving a Protocol Buffers message without breaking old clients relies on:", options: ["Renaming fields freely", "Changing field numbers each release", "Switching the payload to XML", "Keeping field numbers stable and not reusing removed ones"], answer: 3, explain: "Protobuf identifies fields by number on the wire, so numbers must stay stable — add new optional fields, don't repurpose old numbers." },
        { cat: "network", topic: "TCP vs UDP", diff: 2, prompt: "Bandwidth is 'how much data per second'. Latency is:", options: ["How long a single packet takes to travel to its destination", "The number of network hops squared", "The size of a MAC address", "The TLS version in use"], answer: 0, explain: "A link can have high bandwidth yet high latency (e.g. satellite): throughput and delay are different things." },
        { cat: "messaging", topic: "Delivery guarantees", diff: 3, prompt: "Kafka gets close to exactly-once processing using:", options: ["Auto-commit with no acks", "Idempotent producers plus transactions", "Fanout exchanges", "A TTL on every message"], answer: 1, explain: "Idempotent producers dedupe on retry and transactions make read-process-write atomic, giving effectively-once within Kafka." },
        { cat: "data", topic: "Performance", diff: 2, prompt: "A database connection pool improves performance by:", options: ["Encrypting every query", "Sharding the data automatically", "Reusing a set of already-open connections instead of opening one per request", "Caching DNS lookups"], answer: 2, explain: "Opening a DB connection is expensive; a pool hands out and recycles a bounded set, cutting latency and protecting the server." },
        { cat: "apis", topic: "Caching", diff: 2, prompt: "Which HTTP mechanism lets a client revalidate a cached resource cheaply?", options: ["An <span class='mono'>ETag</span> with a conditional <span class='mono'>If-None-Match</span> request", "Always sending the full body", "Disabling caching entirely", "Using POST for reads"], answer: 0, explain: "The server's ETag identifies a version; the client sends If-None-Match and gets a cheap 304 Not Modified if unchanged." },
        { cat: "apis", topic: "Caching", diff: 2, prompt: "Why are <span class='mono'>GET</span> responses cacheable by default but <span class='mono'>POST</span> responses generally not?", options: ["GET is safe and idempotent; POST may change state each time", "POST is faster", "GET uses UDP", "POST responses have no body"], answer: 0, explain: "Caching relies on requests being repeatable without side-effects — true for GET, not for state-changing POST." },
        { cat: "apis", topic: "HTTP methods", diff: 2, prompt: "What is the intended difference between PUT and PATCH?", options: ["PUT replaces the whole resource; PATCH applies a partial update", "PATCH deletes; PUT reads", "They are identical", "PUT is only for collections"], answer: 0, explain: "PUT sends a full representation to replace the resource; PATCH sends only the changes." },
        { cat: "protocols", topic: "WebSockets", diff: 2, prompt: "A WebSocket connection begins as:", options: ["An HTTP request with an <span class='mono'>Upgrade: websocket</span> header", "A raw UDP datagram", "An SMTP session", "A SOAP envelope"], answer: 0, explain: "The client sends an HTTP Upgrade request; on 101 Switching Protocols the connection becomes a persistent WebSocket." },
        { cat: "protocols", topic: "Protocol choice", diff: 3, prompt: "You need simple one-way server→client updates (e.g. a notifications feed) with auto-reconnect over plain HTTP. Which is the lightest fit?", options: ["Server-Sent Events (SSE)", "Full-duplex WebSockets", "gRPC bidirectional streaming", "SOAP polling"], answer: 0, explain: "SSE is a lightweight one-way (server→client) stream over HTTP with built-in reconnection — simpler than WebSockets when you don't need client→server push." },
        { cat: "protocols", topic: "HTTP protocol", diff: 2, prompt: "Which does the HTTP <span class='mono'>3xx</span> status family represent?", options: ["Redirection", "Client errors", "Server errors", "Success"], answer: 0, explain: "1xx info, 2xx success, 3xx redirection, 4xx client error, 5xx server error." },
        { cat: "network", topic: "TLS/security layer", diff: 3, prompt: "In TLS, what is the session (symmetric) key used for, versus the certificate's asymmetric keys?", options: ["Symmetric key encrypts the bulk data fast; asymmetric keys authenticate and exchange that key", "Symmetric keys authenticate; asymmetric keys encrypt all data", "Both do the same thing", "Neither encrypts anything"], answer: 0, explain: "TLS uses asymmetric crypto in the handshake (auth + key exchange), then a fast symmetric key for the actual data." },
        { cat: "network", topic: "OSI layers", diff: 2, prompt: "Which layer manages sessions/dialogues between applications (setup, checkpoint, teardown)?", options: ["Layer 5 — Session", "Layer 4 — Transport", "Layer 6 — Presentation", "Layer 2 — Data Link"], answer: 0, explain: "The Session layer (5) coordinates conversations between endpoints — establishing, maintaining and closing sessions." },
        { cat: "network", topic: "TCP vs UDP", diff: 1, prompt: "Which is a feature of TCP but NOT UDP?", options: ["Retransmission of lost segments", "Using IP addresses", "Having a source port", "Being carried in packets"], answer: 0, explain: "TCP detects loss and retransmits; UDP has no built-in retransmission or ordering." },
        { cat: "messaging", topic: "Delivery guarantees", diff: 2, prompt: "'At-most-once' delivery means:", options: ["A message is delivered zero or one time — never duplicated, but may be lost", "A message is always delivered exactly once", "A message is delivered until acknowledged", "Messages are delivered in random order"], answer: 0, explain: "At-most-once favours no duplicates over reliability — acceptable when losing an occasional message is fine (e.g. metrics)." },
        { cat: "messaging", topic: "Ack & prefetch", diff: 2, prompt: "If a consumer crashes before acking a message (manual ack mode), RabbitMQ will:", options: ["Re-queue/redeliver the message to another consumer", "Delete the message", "Send it to DNS", "Block the exchange forever"], answer: 0, explain: "Without an ack, the broker assumes the work wasn't done and redelivers — which is why consumers must be idempotent." },
        { cat: "messaging", topic: "AMQP & RabbitMQ", diff: 2, prompt: "What makes a RabbitMQ message and queue survive a broker restart?", options: ["Marking the queue durable and the message persistent", "Setting a high prefetch", "Using a fanout exchange", "Nothing — RabbitMQ never loses messages"], answer: 0, explain: "Durability (durable queue + persistent messages) is required to survive restarts; by default queues can be transient." },
        { cat: "data", topic: "Isolation levels", diff: 2, prompt: "'Dirty read' means a transaction:", options: ["Reads data another transaction has written but not yet committed", "Reads its own uncommitted writes", "Reads from a corrupted disk", "Reads an index instead of the table"], answer: 0, explain: "A dirty read sees another transaction's uncommitted change, which may be rolled back — allowed only at READ UNCOMMITTED." },
        { cat: "data", topic: "Transactions", diff: 3, prompt: "Two transactions each hold a lock the other needs. This is a:", options: ["Deadlock", "Dirty read", "Phantom", "Cache miss"], answer: 0, explain: "A deadlock is a cycle of waits; the DB typically detects it and aborts one transaction as the victim." },
        { cat: "data", topic: "Keys & constraints", diff: 1, prompt: "A PRIMARY KEY constraint guarantees the column(s) are:", options: ["Unique and not null", "Indexed but nullable", "Foreign to another table", "Automatically encrypted"], answer: 0, explain: "A primary key uniquely identifies each row and cannot be null; it's usually backed by a unique index." },
      ],
    },

    /* ===================== TEST 6 ===================== */
    { id: "form-6", name: "Test 6", locked: true, blurb: "Status codes & error contracts, DNS/TLS and delivery guarantees.",
      questions: [
        /* extra set */
        { cat: "apis", topic: "API design", diff: 2, prompt: "Letting clients request only certain fields (e.g. <span class='mono'>?fields=id,name</span>) mainly reduces:", options: ["The number of endpoints", "Server CPU for authentication", "TLS handshake time", "Over-fetching and payload size"], answer: 3, explain: "Sparse fieldsets trim the response to what the client needs — a REST answer to GraphQL-style over-fetching." },
        { cat: "protocols", topic: "GraphQL", diff: 2, prompt: "Real-time updates in GraphQL are delivered through:", options: ["Subscriptions, usually over WebSockets", "Extra polling queries", "SOAP faults", "DNS TXT records"], answer: 0, explain: "GraphQL subscriptions push events to the client, typically over a WebSocket transport." },
        { cat: "network", topic: "TCP vs UDP", diff: 2, prompt: "HTTP keep-alive (persistent connections) speeds things up by:", options: ["Encrypting the headers twice", "Reusing one TCP connection for several requests instead of reconnecting each time", "Switching to UDP", "Skipping DNS entirely"], answer: 1, explain: "Reusing the connection avoids repeating the TCP (and TLS) handshake for every request." },
        { cat: "messaging", topic: "Kafka vs RabbitMQ", diff: 2, prompt: "A schema registry (e.g. with Avro) helps a streaming pipeline by:", options: ["Storing user passwords", "Load-balancing brokers", "Enforcing and evolving message schemas so producers and consumers stay compatible", "Encrypting data at rest"], answer: 2, explain: "It versions the message contract centrally, catching incompatible changes before they break consumers." },
        { cat: "data", topic: "CAP & scaling", diff: 3, prompt: "'Read-your-writes' consistency guarantees that:", options: ["All replicas are identical instantly", "Reads never block", "Writes are rejected under load", "A user always sees their own most recent write"], answer: 3, explain: "It's a session guarantee: after you write, your later reads reflect it — even if other users see it slightly later." },
        { cat: "apis", topic: "Status codes", diff: 2, prompt: "A new resource was created by a POST. The most correct response is:", options: ["201 Created with a Location header pointing to it", "200 OK with no body", "204 No Content", "304 Not Modified"], answer: 0, explain: "201 signals creation; the Location header tells the client the new resource's URI." },
        { cat: "apis", topic: "Errors & contracts", diff: 2, prompt: "Which 5xx status means an upstream/dependency the server called failed or timed out?", options: ["502 Bad Gateway / 504 Gateway Timeout", "400 Bad Request", "401 Unauthorized", "201 Created"], answer: 0, explain: "502/504 indicate the server, acting as a gateway/proxy, got a bad or no response from an upstream service." },
        { cat: "apis", topic: "API design", diff: 2, prompt: "Which is the strongest example of a well-designed, predictable API response envelope?", options: ["Consistent field names, ISO-8601 timestamps and stable error codes across endpoints", "Different date formats per endpoint", "Booleans sometimes as 'yes', sometimes as 1", "Field names that change with locale"], answer: 0, explain: "Consistency (naming, types, timestamps, error codes) is what makes an API predictable and easy to integrate against." },
        { cat: "protocols", topic: "SOAP & WSDL", diff: 2, prompt: "WS-Security, part of the SOAP stack, provides:", options: ["Message-level security (signing/encryption of parts of the SOAP message)", "Only transport encryption", "Database backups", "Load balancing"], answer: 0, explain: "WS-Security secures the message itself (not just the transport), so it stays protected across intermediaries." },
        { cat: "protocols", topic: "Protocol choice", diff: 2, prompt: "A partner can only consume a formal, contract-first XML service with a published schema. You should offer:", options: ["SOAP with a WSDL", "A GraphQL endpoint", "A WebSocket stream", "A raw TCP socket"], answer: 0, explain: "Contract-first XML with a machine-readable definition is precisely SOAP + WSDL territory." },
        { cat: "protocols", topic: "REST vs SOAP", diff: 1, prompt: "Which statement about statefulness is generally accurate?", options: ["REST aims to be stateless; SOAP services often participate in stateful WS-* conversations", "REST is always stateful", "SOAP is always stateless", "Neither can hold state"], answer: 0, explain: "REST's constraints favour statelessness; SOAP/WS-* can layer in stateful features like transactions and sessions." },
        { cat: "network", topic: "DNS", diff: 2, prompt: "A CNAME record is used to:", options: ["Alias one hostname to another canonical hostname", "Map a name directly to an IPv6 address", "Route email", "Store a TLS certificate"], answer: 0, explain: "CNAME points a name at another name (e.g. www → app.example.com); AAAA maps to IPv6, MX handles mail." },
        { cat: "network", topic: "TLS/security layer", diff: 2, prompt: "Which is TRUE about HTTPS?", options: ["It is HTTP layered over TLS, so the request/response body and path are encrypted in transit", "It encrypts data at rest in the database", "It replaces TCP", "It works only with SOAP"], answer: 0, explain: "HTTPS = HTTP over TLS; the request/response (including path and headers) is encrypted on the wire (the host may be visible via SNI)." },
        { cat: "network", topic: "Encapsulation", diff: 2, prompt: "At the Transport layer, the unit of data is called a:", options: ["Segment (TCP) / datagram (UDP)", "Frame", "Packet", "Bit"], answer: 0, explain: "PDUs by layer: bits (Physical), frames (Data Link), packets (Network), segments/datagrams (Transport)." },
        { cat: "messaging", topic: "Delivery guarantees", diff: 2, prompt: "Which combination is the pragmatic way most systems approximate 'exactly-once' processing?", options: ["At-least-once delivery + idempotent consumers/dedup", "At-most-once delivery + retries", "No acks + no storage", "Fanout + TTL"], answer: 0, explain: "Reliable delivery (at-least-once) plus idempotent handling yields effectively-once results without true exactly-once transport." },
        { cat: "messaging", topic: "Kafka vs RabbitMQ", diff: 3, prompt: "In Kafka, message ordering is guaranteed:", options: ["Within a single partition", "Across the whole topic globally", "Only if there is one consumer", "Never"], answer: 0, explain: "Kafka preserves order within a partition; to keep related events ordered, route them to the same partition via a key." },
        { cat: "messaging", topic: "Async patterns", diff: 2, prompt: "Publishing an event like <span class='mono'>OrderPlaced</span> that many services subscribe to independently is the:", options: ["Publish/subscribe pattern", "Request/response pattern", "Two-phase commit", "Polling pattern"], answer: 0, explain: "Pub/sub broadcasts an event to all interested subscribers, decoupling the producer from who consumes it." },
        { cat: "data", topic: "CAP & scaling", diff: 3, prompt: "By the CAP theorem, during a network partition a distributed store must sacrifice:", options: ["Either consistency or availability", "Durability", "Its indexes", "Its primary keys"], answer: 0, explain: "CAP: under a partition you choose C or A. 'CP' systems reject some requests to stay consistent; 'AP' stay available but may serve stale data." },
        { cat: "data", topic: "Normalization", diff: 1, prompt: "The main benefit of normalization is:", options: ["Reducing redundancy and update anomalies", "Faster reads in every case", "Removing the need for indexes", "Eliminating foreign keys"], answer: 0, explain: "Normalizing stores each fact once, avoiding anomalies — though heavy read/reporting workloads sometimes denormalize for speed." },
        { cat: "data", topic: "ACID", diff: 2, prompt: "'Atomicity' in ACID means:", options: ["A transaction's operations all commit or all roll back", "Each row is stored atomically on disk", "Reads never block", "The schema is fixed"], answer: 0, explain: "Atomicity is all-or-nothing: a partial transaction never persists." },
      ],
    },

    /* ===================== TEST 7 ===================== */
    { id: "form-7", name: "Test 7", locked: true, blurb: "API authentication, protocol trade-offs and normalization.",
      questions: [
        /* extra set */
        { cat: "apis", topic: "API design", diff: 2, prompt: "A client must create 500 records. The most efficient RESTful approach is usually:", options: ["A bulk/batch endpoint that accepts an array", "500 separate POST requests in a loop", "One large GET request", "A new WebSocket per record"], answer: 0, explain: "A batch endpoint cuts per-request overhead; design it to report per-item success and failure." },
        { cat: "protocols", topic: "HTTP protocol", diff: 2, prompt: "Which HTTP header negotiates response compression such as gzip or brotli?", options: ["<span class='mono'>Accept</span>", "<span class='mono'>Accept-Encoding</span>", "<span class='mono'>Content-Length</span>", "<span class='mono'>Host</span>"], answer: 1, explain: "The client advertises supported encodings via Accept-Encoding; the server replies with Content-Encoding." },
        { cat: "network", topic: "OSI layers", diff: 2, prompt: "A firewall that can allow or block based on the URL path or HTTP headers operates at:", options: ["Layer 2 (data link)", "Layer 4 (transport)", "Layer 7 (application)", "Layer 1 (physical)"], answer: 2, explain: "Inspecting HTTP details is application-layer (L7) filtering; a plain packet filter works at L3/L4 (IP/port)." },
        { cat: "messaging", topic: "Async patterns", diff: 3, prompt: "To send a very large payload through a broker, the 'claim-check' pattern:", options: ["Compresses the entire queue", "Splits it randomly across partitions", "Disables durability for speed", "Stores the blob externally and passes only a reference in the message"], answer: 3, explain: "Keep messages small: put the big object in storage and send its location, which the consumer fetches." },
        { cat: "data", topic: "CAP & scaling", diff: 3, prompt: "Partitioning and sharding both split data, but 'sharding' specifically implies:", options: ["Spreading the partitions across separate nodes/servers", "Splitting a table only within one server", "Encrypting each partition", "Dropping all indexes"], answer: 0, explain: "Sharding is horizontal partitioning across machines (for scale/HA); partitioning can also be just within a single database." },
        { cat: "apis", topic: "API auth", diff: 2, prompt: "In OAuth 2.0, what does the access token represent?", options: ["A time-limited credential authorizing the bearer to call the API on a user's behalf", "The user's raw password", "A database row id", "A TLS certificate"], answer: 0, explain: "The client presents a short-lived access token (often a JWT) instead of the user's credentials to call protected endpoints." },
        { cat: "apis", topic: "API auth", diff: 2, prompt: "A stateless JWT is convenient but has which notable drawback?", options: ["It's hard to revoke before it expires", "It cannot carry claims", "It must be stored server-side per session", "It only works with SOAP"], answer: 0, explain: "Because the server doesn't keep session state, a valid JWT stays valid until expiry unless you add a denylist/short TTLs." },
        { cat: "apis", topic: "API design", diff: 2, prompt: "Which is a good practice for a public API's rate limiting?", options: ["Return 429 Too Many Requests with a Retry-After header", "Silently drop the connection", "Return 200 and ignore extra calls", "Return 404"], answer: 0, explain: "429 + Retry-After tells well-behaved clients exactly how long to back off." },
        { cat: "protocols", topic: "Protocol choice", diff: 3, prompt: "Which factor most argues AGAINST gRPC for a public, browser-facing API?", options: ["Browsers can't speak raw gRPC without a proxy (gRPC-Web), and payloads aren't human-readable", "It's too slow", "It can't define a contract", "It doesn't support streaming"], answer: 0, explain: "gRPC shines internally; for public/browser use its binary format and HTTP/2 framing need gRPC-Web + a proxy, adding friction." },
        { cat: "protocols", topic: "gRPC", diff: 2, prompt: "Protocol Buffers achieve compactness mainly by:", options: ["Encoding fields by numeric tag in binary rather than sending field names as text", "Compressing with gzip only", "Dropping half the fields", "Using XML"], answer: 0, explain: "Protobuf serialises each field by its number in a tight binary form — far smaller than repeating textual keys as JSON/XML do." },
        { cat: "protocols", topic: "WebSockets", diff: 2, prompt: "A downside of long-lived WebSocket connections at scale is:", options: ["Stateful connections complicate load balancing and horizontal scaling", "They can't send binary data", "They require SOAP", "They can't be encrypted"], answer: 0, explain: "Each open socket is server state; balancing, sticky routing and reconnection handling get harder than with stateless HTTP." },
        { cat: "network", topic: "OSI layers", diff: 2, prompt: "Which mapping of protocol to OSI layer is correct?", options: ["IP → Network (L3), TCP → Transport (L4), HTTP → Application (L7)", "IP → Transport, TCP → Network, HTTP → Session", "TCP → Application, IP → Data Link, HTTP → Physical", "HTTP → Transport, TCP → Application, IP → Session"], answer: 0, explain: "IP addresses/routes at L3, TCP delivers at L4, HTTP is an L7 application protocol." },
        { cat: "network", topic: "IP & ports", diff: 2, prompt: "What is the difference between a public and private IP address?", options: ["Private ranges (e.g. 10.x, 192.168.x) are not routable on the public internet and are reused behind NAT", "Private IPs are faster", "Public IPs are encrypted", "There is no difference"], answer: 0, explain: "RFC-1918 private ranges are for internal networks and reach the internet via NAT; public IPs are globally routable." },
        { cat: "network", topic: "DNS", diff: 3, prompt: "DNS changes are often slow to take effect because of:", options: ["TTL-based caching at resolvers along the path", "Encryption overhead", "TCP handshakes", "Foreign keys"], answer: 0, explain: "Resolvers cache records for their TTL, so a changed record propagates only as caches expire." },
        { cat: "messaging", topic: "Exchanges & routing", diff: 3, prompt: "You want <span class='mono'>logs.error.*</span> to reach an alerting queue while <span class='mono'>logs.#</span> reaches an archive. Which exchange type fits?", options: ["Topic", "Direct", "Fanout", "Headers"], answer: 0, explain: "Pattern-based routing with * and # is exactly what a topic exchange provides." },
        { cat: "messaging", topic: "Idempotent consumers", diff: 2, prompt: "Which design makes reprocessing a duplicated <span class='mono'>PaymentCaptured</span> event safe?", options: ["Upsert keyed on the payment id so a repeat is a no-op", "Append a new payment row each time", "Ignore the event id", "Disable acknowledgements"], answer: 0, explain: "An idempotent upsert keyed on a natural id makes the second delivery harmless." },
        { cat: "messaging", topic: "Async patterns", diff: 2, prompt: "The 'transactional outbox' pattern solves which problem?", options: ["Atomically saving state AND publishing an event without a dual-write inconsistency", "Encrypting messages", "Ordering DNS lookups", "Indexing a queue"], answer: 0, explain: "Writing the event to an outbox table in the same DB transaction, then relaying it, avoids the 'DB committed but publish failed' gap." },
        { cat: "data", topic: "Normalization", diff: 2, prompt: "First Normal Form (1NF) requires that:", options: ["Each column holds a single atomic value (no repeating groups/arrays in a cell)", "There are no foreign keys", "Every table has an index", "Data is denormalized for speed"], answer: 0, explain: "1NF forbids multi-valued/repeating fields in a single cell — each intersection of row and column is atomic." },
        { cat: "data", topic: "Keys & constraints", diff: 2, prompt: "A 'natural key' versus a 'surrogate key' is:", options: ["A meaningful real-world identifier vs. a system-generated id (e.g. auto-increment/UUID)", "A foreign key vs. a primary key", "An index vs. a constraint", "A number vs. a string, always"], answer: 0, explain: "Natural keys come from the data (e.g. ISBN); surrogate keys are artificial ids introduced to be stable and simple." },
        { cat: "data", topic: "CAP & scaling", diff: 2, prompt: "Sharding a database means:", options: ["Partitioning rows across nodes by a shard key to scale writes/storage", "Copying the whole DB to every node", "Encrypting each table", "Removing indexes"], answer: 0, explain: "Sharding splits data horizontally across nodes; replication (a different technique) copies data for read scaling/HA." },
      ],
    },

    /* ===================== TEST 8 ===================== */
    { id: "form-8", name: "Test 8", locked: true, blurb: "Contract design, OSI encapsulation and Kafka-vs-RabbitMQ choices.",
      questions: [
        /* extra set */
        { cat: "apis", topic: "REST principles", diff: 2, prompt: "In a hypermedia (HATEOAS) response, a link relation such as <span class='mono'>\"next\"</span> or <span class='mono'>\"self\"</span> tells the client:", options: ["The TLS cipher in use", "The meaning/role of a link so it knows how to navigate", "Which database index was used", "The server's retry count"], answer: 1, explain: "Rel names give links semantics, so the client follows affordances instead of hard-coding URLs." },
        { cat: "protocols", topic: "gRPC", diff: 2, prompt: "Compared with REST/JSON, gRPC/Protobuf payloads are:", options: ["Larger and text-based", "Always XML", "Smaller and binary, but not human-readable", "Identical on the wire"], answer: 2, explain: "Protobuf's compact binary encoding is fast and small, at the cost of readability and easy browser/tooling access." },
        { cat: "network", topic: "IP & ports", diff: 2, prompt: "A host sends traffic destined for another network to its:", options: ["DNS server", "Loopback address", "Switch's MAC address", "Default gateway (router)"], answer: 3, explain: "If the destination isn't on the local subnet, the host forwards the packet to its default gateway to be routed onward." },
        { cat: "messaging", topic: "Ack & prefetch", diff: 2, prompt: "A RabbitMQ consumer rejects a message with <span class='mono'>requeue=true</span>. The broker will:", options: ["Put it back on the queue for redelivery", "Delete it permanently", "Forward it to DNS", "Acknowledge it automatically"], answer: 0, explain: "Requeue returns the message for another attempt; use requeue=false (or a dead-letter exchange) to avoid endless redelivery of poison messages." },
        { cat: "data", topic: "Transactions", diff: 3, prompt: "<span class='mono'>SELECT ... FOR UPDATE</span> is an example of:", options: ["Optimistic concurrency control", "Pessimistic locking — it holds a lock so others must wait", "A covering index", "A materialized view"], answer: 1, explain: "It locks the selected rows for the transaction's duration, preventing concurrent writers — safe, but can reduce concurrency and cause waits." },
        { cat: "apis", topic: "Errors & contracts", diff: 3, prompt: "An API changes a field from a string to an object in v1 without notice. This is bad because:", options: ["It is a breaking change to the contract — existing clients will fail to parse it", "Objects are slower than strings", "JSON forbids objects", "It improves caching"], answer: 0, explain: "Changing a field's type breaks consumers relying on the old shape; such changes belong in a new version." },
        { cat: "apis", topic: "REST principles", diff: 2, prompt: "Which best reflects 'uniform interface', a REST constraint?", options: ["Resources are manipulated through standard methods and representations, consistently", "Each endpoint invents its own verbs", "The server dictates the client's UI", "Every response is HTML"], answer: 0, explain: "A uniform interface (standard methods, resource URIs, self-descriptive messages) is central to REST's simplicity." },
        { cat: "apis", topic: "Versioning", diff: 2, prompt: "Which change can usually be made WITHOUT a new API version?", options: ["Adding a new optional field to a response", "Renaming an existing field", "Removing an endpoint", "Changing a field's data type"], answer: 0, explain: "Additive, optional changes are backward-compatible; renames/removals/type changes break existing clients." },
        { cat: "protocols", topic: "Protocol choice", diff: 2, prompt: "For a public, cache-heavy, browser-consumed API with simple CRUD, the pragmatic default is:", options: ["REST/JSON over HTTPS", "SOAP with WSDL", "Raw TCP", "gRPC without a proxy"], answer: 0, explain: "REST/JSON is the low-friction default for public CRUD APIs — cacheable, browser-friendly and widely understood." },
        { cat: "protocols", topic: "HTTP protocol", diff: 2, prompt: "Which is TRUE about REST-over-HTTP safe methods and caching?", options: ["GET responses can be cached and shared because GET is safe/idempotent", "POST responses are cached by default", "DELETE is a safe method", "PUT must not be idempotent"], answer: 0, explain: "Safe/idempotent GETs are cacheable; state-changing methods generally are not cached." },
        { cat: "protocols", topic: "GraphQL", diff: 3, prompt: "A naive GraphQL resolver that queries the DB once per item in a list causes:", options: ["The N+1 query problem (often fixed with a batching DataLoader)", "A TLS handshake failure", "A DNS loop", "A deadlock by design"], answer: 0, explain: "Resolving a list field per-item fires N extra queries; batching/dataloader coalesces them into one." },
        { cat: "network", topic: "Encapsulation", diff: 2, prompt: "The Data Link layer's PDU is a frame. What does it typically add that other layers don't?", options: ["MAC addresses and often a trailer with a frame-check sequence (CRC)", "A TLS certificate", "A SQL query", "A routing key"], answer: 0, explain: "L2 frames carry source/destination MAC addresses and usually a CRC/FCS trailer for error detection on the link." },
        { cat: "network", topic: "OSI layers", diff: 2, prompt: "Which is an Application-layer (L7) protocol?", options: ["DNS", "IP", "TCP", "Ethernet"], answer: 0, explain: "DNS, HTTP, SMTP and FTP are application-layer; IP is L3, TCP is L4, Ethernet is L2." },
        { cat: "network", topic: "Load balancing layer", diff: 2, prompt: "An L4 load balancer distributes traffic based on:", options: ["IP address and TCP/UDP port, without inspecting the payload", "The HTTP URL path", "Cookies", "The SQL query"], answer: 0, explain: "L4 balancing routes by connection (IP/port) and is protocol-agnostic; L7 inspects application data like URLs/headers." },
        { cat: "messaging", topic: "Kafka vs RabbitMQ", diff: 2, prompt: "Which is a native Kafka concept, not a RabbitMQ one?", options: ["Partitioned topics with consumer-group offsets", "Exchanges and bindings", "Per-message TTL routing to a DLX", "AMQP acknowledgements"], answer: 0, explain: "Partitions + consumer offsets are core Kafka; exchanges/bindings/DLX/AMQP acks are RabbitMQ's model." },
        { cat: "messaging", topic: "Delivery guarantees", diff: 2, prompt: "Turning OFF acknowledgements (auto-ack) in RabbitMQ trades toward:", options: ["Higher throughput but at-most-once (messages can be lost on a crash)", "Exactly-once delivery", "Stronger durability", "Guaranteed ordering"], answer: 0, explain: "Auto-ack acknowledges on delivery, so a crash mid-processing loses the message — faster, but at-most-once." },
        { cat: "messaging", topic: "Dead-letter & TTL", diff: 3, prompt: "A common use of a DLQ plus a delayed re-queue is to implement:", options: ["A retry-with-backoff mechanism for transient failures", "Encryption at rest", "Database sharding", "DNS caching"], answer: 0, explain: "Dead-lettering failed messages to a delay queue and re-injecting them later gives you retries with backoff." },
        { cat: "data", topic: "Indexing", diff: 2, prompt: "A 'covering index' is one that:", options: ["Contains all columns a query needs, so the DB answers it from the index alone", "Covers every table", "Automatically encrypts data", "Replaces the primary key"], answer: 0, explain: "If the index includes all selected/filtered columns, the engine skips the table lookup — an index-only scan." },
        { cat: "data", topic: "Isolation levels", diff: 2, prompt: "'Phantom read' refers to:", options: ["A re-run query returning newly-inserted rows matching the filter", "Reading uncommitted data", "A row changing value between reads", "A dropped index"], answer: 0, explain: "Phantoms are new rows appearing in a repeated range query; only Serializable (or range locks) prevents them." },
        { cat: "data", topic: "SQL vs NoSQL", diff: 2, prompt: "A wide-column store (e.g. Cassandra) is typically chosen for:", options: ["Very high write throughput and horizontal scale with tunable consistency", "Complex ad-hoc joins", "Strict global ACID across rows", "Small single-node datasets"], answer: 0, explain: "Cassandra-style stores scale writes across nodes with tunable consistency; they don't do relational joins/global ACID." },
      ],
    },

    /* ===================== TEST 9 ===================== */
    { id: "form-9", name: "Test 9", locked: true, blurb: "REST maturity, load balancing and dead-letter / retry design.",
      questions: [
        /* extra set */
        { cat: "apis", topic: "REST principles", diff: 3, prompt: "An API that exposes many resource URIs but tunnels every operation through <span class='mono'>POST</span> sits at which Richardson Maturity level?", options: ["Level 0", "Level 3", "Level 1", "Level 2"], answer: 2, explain: "Level 1 introduces resource URIs but doesn't use HTTP verbs properly; Level 2 adds correct verbs and status codes." },
        { cat: "protocols", topic: "SOAP & WSDL", diff: 2, prompt: "OpenAPI (Swagger) is to REST roughly what ___ is to SOAP.", options: ["WSDL", "TLS", "TCP", "JSON"], answer: 0, explain: "Both are machine-readable service contracts: WSDL describes SOAP services; OpenAPI describes REST APIs." },
        { cat: "network", topic: "IP & ports", diff: 3, prompt: "In CIDR notation, <span class='mono'>192.168.1.0/24</span> means:", options: ["24 usable hosts", "The first 24 bits are the network prefix (a 256-address block)", "24 separate subnets", "A 24-hour DHCP lease"], answer: 1, explain: "/24 = 24 network bits, leaving 8 host bits → 256 addresses (254 usable)." },
        { cat: "messaging", topic: "Async patterns", diff: 2, prompt: "A 'durable subscription' means a subscriber:", options: ["Never acknowledges messages", "Only ever gets the newest message", "Bypasses the exchange", "Still receives messages that were published while it was offline"], answer: 3, explain: "The broker retains messages for a durable subscriber so nothing is missed during downtime, unlike a non-durable one." },
        { cat: "data", topic: "Joins", diff: 2, prompt: "An ORM that lazily loads each parent's children one row at a time in a loop causes:", options: ["A deadlock", "A dirty read", "The N+1 query problem", "A dropped index"], answer: 2, explain: "One query for the parents plus one per parent for children = N+1 round-trips; fix with a join or eager/batch loading." },
        { cat: "apis", topic: "REST principles", diff: 3, prompt: "On the Richardson Maturity Model, an API that uses resource URIs and multiple HTTP verbs correctly, but no hypermedia, is at:", options: ["Level 2", "Level 0", "Level 1", "Level 3"], answer: 0, explain: "Level 0: HTTP as a tunnel; L1: resources; L2: HTTP verbs/status codes used properly; L3: adds hypermedia (HATEOAS)." },
        { cat: "apis", topic: "Pagination", diff: 2, prompt: "Which response detail most helps a client consume a paginated list reliably?", options: ["A next-page cursor/link and a clear indicator when there are no more pages", "Only the total count", "A random subset each call", "Nothing — clients should guess"], answer: 0, explain: "A stable cursor/next link plus an end signal lets clients page deterministically without off-by-one errors." },
        { cat: "apis", topic: "Idempotency", diff: 2, prompt: "Which HTTP method is NOT idempotent, so retries risk creating duplicates?", options: ["POST", "PUT", "DELETE", "GET"], answer: 0, explain: "POST typically creates a new resource each call; PUT/DELETE/GET are idempotent." },
        { cat: "protocols", topic: "REST vs SOAP", diff: 2, prompt: "Which is a legitimate reason to still choose SOAP today?", options: ["Built-in WS-* standards for security, reliable messaging and transactions demanded by a partner", "It's smaller and faster than JSON", "Browsers prefer it", "It needs no schema"], answer: 0, explain: "SOAP persists where formal WS-* guarantees and existing enterprise/partner contracts require them." },
        { cat: "protocols", topic: "SOAP & WSDL", diff: 2, prompt: "A SOAP <span class='mono'>Fault</span> element is the SOAP equivalent of:", options: ["A structured error response", "A success payload", "A TLS alert", "A database commit"], answer: 0, explain: "SOAP faults carry error information (code, reason, detail) inside the message body, akin to a REST error object." },
        { cat: "protocols", topic: "Protocol choice", diff: 2, prompt: "You must integrate with a legacy system that exposes only a SOAP/WSDL endpoint. The realistic approach is:", options: ["Consume the SOAP service (optionally wrap it behind your own REST facade)", "Demand they rewrite to GraphQL first", "Use raw UDP", "Poll their database directly"], answer: 0, explain: "Integrate with what exists — call the SOAP service, and a REST/anti-corruption facade can shield the rest of your system." },
        { cat: "network", topic: "Load balancing layer", diff: 3, prompt: "'Sticky sessions' on a load balancer are sometimes needed because:", options: ["Some apps keep per-user state on one server, so requests must return to it", "They encrypt traffic", "They speed up DNS", "They shard the database"], answer: 0, explain: "Stateful servers require affinity so a user's later requests hit the same node — a reason to prefer stateless designs where possible." },
        { cat: "network", topic: "TCP vs UDP", diff: 2, prompt: "QUIC (the basis of HTTP/3) is notable because it:", options: ["Provides reliable, multiplexed, encrypted streams over UDP", "Replaces IP", "Is slower than TCP by design", "Only works on LANs"], answer: 0, explain: "QUIC runs over UDP but adds reliability, multiplexing and built-in TLS, avoiding TCP head-of-line blocking." },
        { cat: "network", topic: "TLS/security layer", diff: 2, prompt: "Mutual TLS (mTLS) differs from standard TLS in that:", options: ["Both client and server present certificates to authenticate each other", "It skips encryption", "It only encrypts the client side", "It replaces the need for TCP"], answer: 0, explain: "mTLS authenticates both parties by certificate — common in service-to-service/zero-trust setups." },
        { cat: "messaging", topic: "Queues & DLQ", diff: 2, prompt: "A message keeps failing and being redelivered forever ('poison message'). The standard fix is:", options: ["Cap retries and dead-letter it after N attempts", "Increase prefetch to infinity", "Delete the queue", "Switch to fanout"], answer: 0, explain: "Bounding retries and dead-lettering the poison message stops the redelivery loop and preserves it for inspection." },
        { cat: "messaging", topic: "AMQP & RabbitMQ", diff: 2, prompt: "Publisher confirms in RabbitMQ give the producer:", options: ["An async acknowledgement that the broker has taken responsibility for the message", "A guarantee the consumer processed it", "A faster TCP handshake", "A new exchange"], answer: 0, explain: "Publisher confirms tell the producer the broker safely received/enqueued the message — not that a consumer handled it." },
        { cat: "messaging", topic: "Kafka vs RabbitMQ", diff: 2, prompt: "A Kafka 'consumer group' lets you:", options: ["Share a topic's partitions among consumers so each partition is read by one member", "Broadcast every message to every member", "Store messages in SQL", "Encrypt the topic"], answer: 0, explain: "Within a group, partitions are divided among members for scale; different groups each get the full stream independently." },
        { cat: "data", topic: "Transactions", diff: 3, prompt: "Optimistic concurrency control works by:", options: ["Letting transactions proceed and checking a version/timestamp at commit, retrying on conflict", "Locking every row on read", "Disabling isolation", "Never allowing concurrent writes"], answer: 0, explain: "Optimistic control assumes conflicts are rare: it validates a version at commit and retries if another writer won." },
        { cat: "data", topic: "CAP & scaling", diff: 2, prompt: "Read replicas are primarily used to:", options: ["Scale read throughput and offload the primary (at the cost of possible replication lag)", "Guarantee stronger write consistency", "Encrypt data at rest", "Enforce foreign keys"], answer: 0, explain: "Replicas serve reads to relieve the primary; the trade-off is eventual consistency/lag on those replicas." },
        { cat: "data", topic: "Joins", diff: 3, prompt: "A query joins two 10-million-row tables with no index on the join columns. The likely outcome is:", options: ["A slow, scan-heavy join (e.g. hash/nested-loop over full table scans)", "An instant index-only scan", "A syntax error", "Automatic sharding"], answer: 0, explain: "Without supporting indexes the planner must scan and hash/loop over huge inputs — the classic missing-index performance trap." },
      ],
    },

    /* ===================== TEST 10 ===================== */
    { id: "form-10", name: "Test 10", locked: true, blurb: "A harder mixed set spanning all five domains.",
      questions: [
        /* extra set */
        { cat: "apis", topic: "HTTP protocol", diff: 2, prompt: "A client sends <span class='mono'>Accept: application/xml</span>. A well-behaved API should:", options: ["Return XML if it can, otherwise respond 406 Not Acceptable", "Ignore it and always return JSON", "Return 500 Internal Server Error", "Silently switch to SOAP"], answer: 0, explain: "Content negotiation honours Accept; if no acceptable representation exists, 406 is the correct signal." },
        { cat: "protocols", topic: "Protocol choice", diff: 2, prompt: "REST is resource-oriented; gRPC is closer to which style?", options: ["Publish/subscribe messaging", "RPC — calling remote methods/procedures", "Batch ETL", "Plain file transfer"], answer: 1, explain: "gRPC models method calls (Remote Procedure Call) with typed requests/responses, versus REST's nouns-and-verbs resources." },
        { cat: "network", topic: "TCP vs UDP", diff: 1, prompt: "The <span class='mono'>ping</span> utility uses which protocol?", options: ["TCP", "HTTP", "ICMP", "SMTP"], answer: 2, explain: "ping sends ICMP echo request/reply messages to test reachability and round-trip time." },
        { cat: "messaging", topic: "Async patterns", diff: 2, prompt: "One message consumed by exactly one of several workers is the ___ pattern; one message delivered to all subscribers is ___.", options: ["publish/subscribe; work queue", "saga; outbox", "direct; headers", "work queue; publish/subscribe"], answer: 3, explain: "A work queue load-balances one message to a single worker; pub/sub broadcasts each message to every subscriber." },
        { cat: "data", topic: "SQL vs NoSQL", diff: 2, prompt: "Storing large user-uploaded files as BLOBs inside your main OLTP database tends to:", options: ["Bloat the database and hurt performance — object storage plus a URL is usually better", "Improve query speed", "Guarantee durability better than disk", "Eliminate the need for backups"], answer: 0, explain: "Big binaries swell backups, cache and I/O; keep them in object storage (e.g. S3) and store just the reference." },
        { cat: "apis", topic: "API design", diff: 3, prompt: "Which is the best fix for an endpoint <span class='mono'>GET /orders</span> that returns 50,000 rows and times out?", options: ["Add pagination, filtering and sensible defaults/limits", "Return 500 faster", "Switch it to POST", "Remove the endpoint"], answer: 0, explain: "Large collections need server-side pagination and filters with a default page size — never dump the whole set." },
        { cat: "apis", topic: "API auth", diff: 3, prompt: "Why is putting an API key in the URL query string discouraged?", options: ["URLs are logged by servers/proxies and stored in history, leaking the secret", "Query strings can't hold text", "It breaks JSON", "It disables caching"], answer: 0, explain: "Secrets in URLs end up in access logs, browser history and referrers; use the Authorization header instead." },
        { cat: "apis", topic: "Status codes", diff: 2, prompt: "A conditional update fails because the resource changed since the client fetched it. The apt status is:", options: ["409 Conflict (or 412 Precondition Failed)", "200 OK", "404 Not Found", "301 Moved Permanently"], answer: 0, explain: "A concurrent-modification/version mismatch is a 409 Conflict, or 412 when using If-Match preconditions." },
        { cat: "protocols", topic: "gRPC", diff: 3, prompt: "Which gRPC call type keeps one request but returns a stream of responses?", options: ["Server streaming", "Unary", "Client streaming", "Bidirectional streaming"], answer: 0, explain: "gRPC supports unary, server-streaming (1 req → many resp), client-streaming and bidirectional streaming." },
        { cat: "protocols", topic: "Protocol choice", diff: 3, prompt: "Which requirement most strongly favours an event/message protocol over synchronous REST between services?", options: ["Producers must not block or fail when a downstream consumer is slow or temporarily down", "You need the lowest possible single-call latency", "You want simple browser access", "You need URL-based caching"], answer: 0, explain: "Asynchronous messaging decouples availability: the producer emits an event and moves on regardless of consumer health." },
        { cat: "protocols", topic: "WebSockets", diff: 3, prompt: "A resilient WebSocket client design should include:", options: ["Automatic reconnect with backoff and re-subscription of state", "A single connection that never reconnects", "Polling instead of the socket", "Disabling TLS to reconnect faster"], answer: 0, explain: "Networks drop; robust clients reconnect with backoff and restore subscriptions/state on the new connection." },
        { cat: "network", topic: "OSI layers", diff: 3, prompt: "A firewall rule that blocks TCP port 22 but allows 443 is acting on information from which layers?", options: ["Transport (port) and Network (IP)", "Only Physical", "Only Application", "Only Presentation"], answer: 0, explain: "Port-based filtering reads Transport-layer ports and Network-layer IPs — an L3/L4 packet filter." },
        { cat: "network", topic: "DNS", diff: 3, prompt: "Round-robin DNS returns multiple A records to spread load, but a weakness is:", options: ["No health awareness — it may hand out a dead server's IP", "It encrypts nothing", "It only works with IPv6", "It requires SOAP"], answer: 0, explain: "Plain round-robin DNS rotates IPs blindly; without health checks it can send clients to a downed node." },
        { cat: "network", topic: "TCP vs UDP", diff: 3, prompt: "'Head-of-line blocking' on an HTTP/2-over-TCP connection happens because:", options: ["A lost/slow TCP segment stalls everything behind it on that connection", "UDP reorders packets", "DNS is slow", "TLS blocks reads"], answer: 0, explain: "TCP's in-order delivery means one lost segment holds up later data; QUIC/HTTP-3 over UDP avoids transport-level HoL blocking." },
        { cat: "messaging", topic: "Delivery guarantees", diff: 3, prompt: "A consumer processes a message, then crashes BEFORE acking. With manual acks the result is:", options: ["Redelivery — the work may run twice, so it must be idempotent", "Silent loss", "Exactly-once automatically", "The broker deletes the queue"], answer: 0, explain: "The unacked message is redelivered, so the side-effects can repeat — idempotency is the safeguard." },
        { cat: "messaging", topic: "Async patterns", diff: 3, prompt: "A saga (choreographed via events) is used to:", options: ["Coordinate a multi-service business transaction with compensating actions instead of a distributed lock", "Encrypt messages end to end", "Shard a single database", "Cache DNS responses"], answer: 0, explain: "Sagas keep long-running, cross-service transactions consistent using events and compensations rather than 2-phase commit/locks." },
        { cat: "messaging", topic: "Exchanges & routing", diff: 2, prompt: "Which statement about a RabbitMQ queue is correct?", options: ["A queue holds messages until a consumer acks them (or they expire / are dead-lettered)", "A queue routes by pattern", "A queue is where producers publish directly by design", "A queue encrypts messages"], answer: 0, explain: "Exchanges route; queues buffer messages for consumers and hold them until acked, expired or dead-lettered." },
        { cat: "data", topic: "Isolation levels", diff: 3, prompt: "Choosing SERIALIZABLE everywhere by default is often avoided because:", options: ["It reduces concurrency/throughput due to heavier locking or more retries", "It allows dirty reads", "It disables durability", "It removes indexes"], answer: 0, explain: "Serializable is safest but costly; teams pick the weakest level that still prevents the anomalies that matter for correctness." },
        { cat: "data", topic: "Denormalization", diff: 3, prompt: "A read-heavy reporting dashboard is slow due to many joins. A reasonable step is:", options: ["Denormalize or add a materialized view / read model for those reads", "Drop all indexes", "Lower the isolation to READ UNCOMMITTED permanently", "Delete foreign keys"], answer: 0, explain: "Precomputed/denormalized read models (e.g. materialized views, CQRS) trade some redundancy for fast reads." },
        { cat: "data", topic: "CAP & scaling", diff: 3, prompt: "'Eventual consistency' means:", options: ["Replicas may briefly differ but converge to the same value if no new writes occur", "Data is never consistent", "Writes are rejected during partitions", "Reads always see the latest write"], answer: 0, explain: "AP systems accept temporary divergence across replicas that eventually converges — the trade for high availability." },
      ],
    },
  ],
};
